@OptIn(ExperimentalCoroutinesApi::class)
@Composable
fun SplashScreen(navController: NavController) {
    val context = LocalContext.current
    val userPreferencesRepository = UserPreferencesRepository(context)
    val userData by userPreferencesRepository.userData.collectAsState(initial = UserData(null, null, null))
    var showError by remember { mutableStateOf(false) }
    val connection by connectivityState()
    val isConnected = connection === ConnectionStatus.Available
    val scope = rememberCoroutineScope()

    // Lanzar verificación desde una corutina; la lógica heavy está en la función suspend top-level
    fun verifySession() {
        scope.launch {
            performSessionVerification(context, navController, userPreferencesRepository, userData, isConnected) { showError = it }
        }
    }

    LaunchedEffect(key1 = isConnected) {
        if (isConnected) {
            verifySession()
        } else {
            showError = true
        }
    }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(
                        Color.White,
                        Color(0xFF2196F3), // azul
                        Color(0xFF4CAF50)  // verde
                    )
                )
            ),
        contentAlignment = Alignment.Center
    ) {
        Column(
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {
            Image(
                painter = painterResource(id = R.drawable.logo),
                contentDescription = "Logo",
                modifier = Modifier
                    .size(150.dp)
                    .clip(CircleShape)
            )
            Spacer(modifier = Modifier.height(24.dp))
            if (showError) {
                Text(
                    text = stringResource(R.string.network_error_description),
                    style = MaterialTheme.typography.bodyMedium,
                    textAlign = TextAlign.Center,
                    modifier = Modifier.padding(horizontal = 32.dp)
                )
                Spacer(modifier = Modifier.height(16.dp))
                Button(onClick = { verifySession() }) {
                    Text(text = stringResource(R.string.retry))
                }
            } else {
                CircularProgressIndicator()
            }
        }
    }
}

// Mover la lógica de verificación a una función suspend top-level para evitar problemas con
// funciones locales dentro de un @Composable que podrían capturar llamadas composables.
suspend fun performSessionVerification(
    context: Context,
    navController: NavController,
    userPreferencesRepository: UserPreferencesRepository,
    userData: UserData?,
    isConnected: Boolean,
    onShowError: (Boolean) -> Unit
) {
    onShowError(false)
    // Mantener la pausa simulada
    delay(1500)
    if (!isConnected) {
        onShowError(true)
        return
    }

    // Check current firebase user and existing userData
    val firebaseUser = FirebaseAuth.getInstance().currentUser
    // Si el usuario ya tiene session local, ir a home
    if (userData?.userId != null) {
        navController.navigate("home") { popUpTo("splash") { inclusive = true } }
        return
    }

    // Leer preferencia de aceptación de términos de forma suspend
    val acceptedPref = userPreferencesRepository.protectionTermsAccepted.first()

    if (firebaseUser != null) {
        try {
            val snap = com.google.firebase.firestore.FirebaseFirestore.getInstance()
                .collection("users").document(firebaseUser.uid).get().await()
            val roleStr = snap.getString("role")
            val name = snap.getString("name") ?: ""
            userPreferencesRepository.updateUserData(firebaseUser.uid, roleStr, name)
        } catch (_: Exception) {
            // ignore, defaults later
        }

        // Si no aceptó términos, ir a términos
        if (!acceptedPref) {
            navController.navigate("terms") { popUpTo("splash") { inclusive = true } }
            return
        }

        navController.navigate("home") { popUpTo("splash") { inclusive = true } }
        return
    }

    // No hay sesión: si no aceptó términos -> mostrar términos; si sí -> abrir LoginActivity
    if (!acceptedPref) {
        navController.navigate("terms") { popUpTo("splash") { inclusive = true } }
        return
    }

    val activity = (context as? Activity)
    activity?.let {
        it.startActivity(Intent(it, LoginActivity::class.java))
        it.finish()
    } ?: run {
        navController.popBackStack(0, inclusive = true)
    }
}

package com.example.appcolegios.auth

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.verticalScroll
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.navigation.NavController
import com.example.appcolegios.data.UserPreferencesRepository
import kotlinx.coroutines.launch

@Composable
fun TermsScreen(navController: NavController, userPrefs: UserPreferencesRepository) {
    val scope = rememberCoroutineScope()

    Box(modifier = Modifier
        .fillMaxSize()
        .background(
            Brush.verticalGradient(listOf(Color.White, Color(0xFFF1F6F9)))
        )) {
        Column(modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
            .verticalScroll(rememberScrollState()),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Spacer(modifier = Modifier.height(12.dp))
            Text(text = "Términos de protección de menores", style = MaterialTheme.typography.headlineSmall)
            Spacer(modifier = Modifier.height(8.dp))
            Text(text = "Antes de continuar, por favor lee y acepta los términos de protección de menores.", style = MaterialTheme.typography.bodyMedium)
            Spacer(modifier = Modifier.height(16.dp))

            // Texto de términos (resumen profesional); se recomienda enlazar a política completa en web
            Text(text = buildString {
                append("1. Privacidad: No se compartirán fotos o datos personales de menores sin consentimiento explícito de los padres/tutores.\n\n")
                append("2. Uso de imágenes: Las fotos de perfil y cualquier imagen subidas por usuarios serán almacenadas en Firebase Storage y sólo referenciadas por URL en la base de datos.\n\n")
                append("3. Acceso y control: Sólo personal autorizado (administradores y docentes con permisos) podrá editar información académica sensible. Los padres y estudiantes pueden ver la información asociada a su cuenta.\n\n")
                append("4. Reportes y moderación: Cualquier contenido inadecuado puede ser reportado y será revisado por el equipo del colegio.\n\n")
                append("5. Derechos de los tutores: Los padres/tutores pueden solicitar eliminación o rectificación de datos personales.\n\n")
                append("6. Contacto: Para dudas relacionadas con la protección de menores y privacidad, contacta al responsable de privacidad del colegio.")
            }, style = MaterialTheme.typography.bodySmall, fontSize = 14.sp)

            Spacer(modifier = Modifier.height(24.dp))

            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                Button(onClick = {
                    // Rechazar -> cerrar aplicación o volver a splash y no permitir continuar al login
                    // Aquí navegamos al splash con error (podríamos mostrar un dialog explicativo)
                    navController.popBackStack()
                }) {
                    Text("Rechazar")
                }

                Button(onClick = {
                    scope.launch {
                        userPrefs.setProtectionTermsAccepted(true)
                        // Navegar al login (start activity) como hace la lógica actual en Splash
                        navController.navigate("login") { popUpTo("splash") { inclusive = true } }
                    }
                }) {
                    Text("Aceptar")
                }
            }
        }
    }
}

package com.example.appcolegios.data

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.booleanPreferencesKey
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.intPreferencesKey
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import com.example.appcolegios.data.model.Role
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "user_prefs")

class UserPreferencesRepository(context: Context) {

    private val dataStore = context.dataStore

    private object PreferencesKeys {
        val USER_ID = stringPreferencesKey("user_id")
        val USER_ROLE = stringPreferencesKey("user_role")
        val USER_NAME = stringPreferencesKey("user_name")

        // Nuevas preferencias
        val APP_LANGUAGE = stringPreferencesKey("app_language") // "es" | "en"
        val DARK_MODE = booleanPreferencesKey("dark_mode_enabled")
        val FONT_SIZE = intPreferencesKey("font_size_enum") // 0=Small,1=Normal,2=Large
        val PUSH_NOTIFICATIONS = booleanPreferencesKey("push_notifications_enabled")
    }

    val userData: Flow<UserData> = dataStore.data
        .map { preferences ->
            UserData(
                userId = preferences[PreferencesKeys.USER_ID],
                role = preferences[PreferencesKeys.USER_ROLE],
                name = preferences[PreferencesKeys.USER_NAME]
            )
        }

    // Flows para nuevas preferencias de la app
    val appLanguage: Flow<String?> = dataStore.data.map { it[PreferencesKeys.APP_LANGUAGE] }
    val darkModeEnabled: Flow<Boolean> = dataStore.data.map { it[PreferencesKeys.DARK_MODE] ?: false }
    val fontSizeEnum: Flow<Int> = dataStore.data.map { it[PreferencesKeys.FONT_SIZE] ?: 1 }
    val pushNotificationsEnabled: Flow<Boolean> = dataStore.data.map { it[PreferencesKeys.PUSH_NOTIFICATIONS] ?: true }

    // Actualiza userId, role y displayName
    suspend fun updateUserData(userId: String?, role: String?, name: String?) {
        dataStore.edit { preferences ->
            if (userId == null) {
                preferences.remove(PreferencesKeys.USER_ID)
            } else {
                preferences[PreferencesKeys.USER_ID] = userId
            }
            if (role == null) {
                preferences.remove(PreferencesKeys.USER_ROLE)
            } else {
                preferences[PreferencesKeys.USER_ROLE] = role
            }
            if (name == null) {
                preferences.remove(PreferencesKeys.USER_NAME)
            } else {
                preferences[PreferencesKeys.USER_NAME] = name
            }
        }
    }

    // Setters para nuevas preferencias
    suspend fun setAppLanguage(lang: String) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.APP_LANGUAGE] = lang }
    }

    suspend fun setDarkMode(enabled: Boolean) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.DARK_MODE] = enabled }
    }

    suspend fun setFontSizeEnum(value: Int) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.FONT_SIZE] = value }
    }

    suspend fun setPushNotificationsEnabled(enabled: Boolean) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.PUSH_NOTIFICATIONS] = enabled }
    }

    // Limpia todos los datos del usuario al cerrar sesión
    suspend fun clearAllUserData() {
        dataStore.edit { preferences ->
            preferences.clear()
        }
    }
}

data class UserData(
    val userId: String?,
    val role: String?, // mantener string para compatibilidad; usar helper de conversión
    val name: String?
) {
    // Si no hay rol (null o vacío) retornamos null para evitar asumir ADMIN por defecto
    val roleEnum: Role? get() = when {
        role.isNullOrBlank() -> null
        else -> Role.fromString(role)
    }
}

package com.example.appcolegios.data

import android.content.Context
import androidx.datastore.core.DataStore
import androidx.datastore.preferences.core.Preferences
import androidx.datastore.preferences.core.booleanPreferencesKey
import androidx.datastore.preferences.core.edit
import androidx.datastore.preferences.core.intPreferencesKey
import androidx.datastore.preferences.core.stringPreferencesKey
import androidx.datastore.preferences.preferencesDataStore
import com.example.appcolegios.data.model.Role
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.map

private val Context.dataStore: DataStore<Preferences> by preferencesDataStore(name = "user_prefs")

class UserPreferencesRepository(context: Context) {

    private val dataStore = context.dataStore

    private object PreferencesKeys {
        val USER_ID = stringPreferencesKey("user_id")
        val USER_ROLE = stringPreferencesKey("user_role")
        val USER_NAME = stringPreferencesKey("user_name")

        // Nuevas preferencias
        val APP_LANGUAGE = stringPreferencesKey("app_language") // "es" | "en"
        val DARK_MODE = booleanPreferencesKey("dark_mode_enabled")
        val FONT_SIZE = intPreferencesKey("font_size_enum") // 0=Small,1=Normal,2=Large
        val PUSH_NOTIFICATIONS = booleanPreferencesKey("push_notifications_enabled")
        // Aceptación de términos de protección de menores
        val PROTECTION_TERMS_ACCEPTED = booleanPreferencesKey("protection_terms_accepted")
    }

    val userData: Flow<UserData> = dataStore.data
        .map { preferences ->
            UserData(
                userId = preferences[PreferencesKeys.USER_ID],
                role = preferences[PreferencesKeys.USER_ROLE],
                name = preferences[PreferencesKeys.USER_NAME]
            )
        }

    // Flows para nuevas preferencias de la app
    val appLanguage: Flow<String?> = dataStore.data.map { it[PreferencesKeys.APP_LANGUAGE] }
    val darkModeEnabled: Flow<Boolean> = dataStore.data.map { it[PreferencesKeys.DARK_MODE] ?: false }
    val fontSizeEnum: Flow<Int> = dataStore.data.map { it[PreferencesKeys.FONT_SIZE] ?: 1 }
    val pushNotificationsEnabled: Flow<Boolean> = dataStore.data.map { it[PreferencesKeys.PUSH_NOTIFICATIONS] ?: true }
    val protectionTermsAccepted: Flow<Boolean> = dataStore.data.map { it[PreferencesKeys.PROTECTION_TERMS_ACCEPTED] ?: false }

    // Actualiza userId, role y displayName
    suspend fun updateUserData(userId: String?, role: String?, name: String?) {
        dataStore.edit { preferences ->
            if (userId == null) {
                preferences.remove(PreferencesKeys.USER_ID)
            } else {
                preferences[PreferencesKeys.USER_ID] = userId
            }
            if (role == null) {
                preferences.remove(PreferencesKeys.USER_ROLE)
            } else {
                preferences[PreferencesKeys.USER_ROLE] = role
            }
            if (name == null) {
                preferences.remove(PreferencesKeys.USER_NAME)
            } else {
                preferences[PreferencesKeys.USER_NAME] = name
            }
        }
    }

    // Setters para nuevas preferencias
    suspend fun setAppLanguage(lang: String) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.APP_LANGUAGE] = lang }
    }

    suspend fun setDarkMode(enabled: Boolean) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.DARK_MODE] = enabled }
    }

    suspend fun setFontSizeEnum(value: Int) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.FONT_SIZE] = value }
    }

    suspend fun setPushNotificationsEnabled(enabled: Boolean) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.PUSH_NOTIFICATIONS] = enabled }
    }

    // Guardar/leer aceptación de términos de protección de menores
    suspend fun setProtectionTermsAccepted(accepted: Boolean) {
        dataStore.edit { prefs -> prefs[PreferencesKeys.PROTECTION_TERMS_ACCEPTED] = accepted }
    }

    // Limpia todos los datos del usuario al cerrar sesión
    suspend fun clearAllUserData() {
        dataStore.edit { preferences ->
            preferences.clear()
        }
    }
}

data class UserData(
    val userId: String?,
    val role: String?, // mantener string para compatibilidad; usar helper de conversión
    val name: String?
) {
    // Si no hay rol (null o vacío) retornamos null para evitar asumir ADMIN por defecto
    val roleEnum: Role? get() = when {
        role.isNullOrBlank() -> null
        else -> Role.fromString(role)
    }
}

